import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    throw err;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

server/routes.ts.content:
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { 
  insertParkingSpotSchema, 
  insertBookingSchema, 
  insertWalletTransactionSchema,
  insertVehicleSchema,
  insertVendorProfileSchema,
  insertUserSchema
} from "@shared/schema";
import { fromZodError } from "zod-validation-error";

export async function registerRoutes(app: Express): Promise<Server> {
  // Helper function for error handling
  const handleError = (res: any, error: any, message = "Internal server error") => {
    console.error(error);
    return res.status(500).json({ error: message });
  };

  // Helper function for validation errors
  const handleValidationError = (res: any, error: any) => {
    const validationError = fromZodError(error);
    return res.status(400).json({ error: validationError.message });
  };

  // ========================================
  // PARKING SPOTS ROUTES
  // ========================================

  // Get all parking spots with optional filters
  app.get("/api/spots", async (req, res) => {
    try {
      const { query, city } = req.query;
      const spots = await storage.getParkingSpotsWithFilters(
        query as string, 
        city as string
      );
      res.json(spots);
    } catch (error) {
      handleError(res, error, "Failed to fetch parking spots");
    }
  });

  // Get single parking spot
  app.get("/api/spots/:id", async (req, res) => {
    try {
      const spot = await storage.getParkingSpot(req.params.id);
      if (!spot) {
        return res.status(404).json({ error: "Parking spot not found" });
      }
      res.json(spot);
    } catch (error) {
      handleError(res, error, "Failed to fetch parking spot");
    }
  });

  // Create new parking spot (vendor only)
  app.post("/api/spots", async (req, res) => {
    try {
      const validatedData = insertParkingSpotSchema.parse(req.body);
      const spot = await storage.createParkingSpot(validatedData);
      res.status(201).json(spot);
    } catch (error) {
      if (error.name === "ZodError") {
        return handleValidationError(res, error);
      }
      handleError(res, error, "Failed to create parking spot");
    }
  });

  // Update parking spot
  app.patch("/api/spots/:id", async (req, res) => {
    try {
      const updates = req.body;

      // Basic validation for critical fields
      if (updates.availableSpots !== undefined && (updates.availableSpots < 0 || !Number.isInteger(updates.availableSpots))) {
        return res.status(400).json({ error: "Available spots must be a non-negative integer" });
      }
      if (updates.totalSpots !== undefined && (updates.totalSpots <= 0 || !Number.isInteger(updates.totalSpots))) {
        return res.status(400).json({ error: "Total spots must be a positive integer" });
      }
      if (updates.pricePerHour !== undefined && (updates.pricePerHour <= 0 || !Number.isInteger(updates.pricePerHour))) {
        return res.status(400).json({ error: "Price per hour must be a positive integer" });
      }

      const updatedSpot = await storage.updateParkingSpot(req.params.id, updates);
      if (!updatedSpot) {
        return res.status(404).json({ error: "Parking spot not found" });
      }
      res.json(updatedSpot);
    } catch (error) {
      handleError(res, error, "Failed to update parking spot");
    }
  });

  // ========================================
  // BOOKINGS ROUTES
  // ========================================

  // Get user's bookings
  app.get("/api/bookings/user/:userId", async (req, res) => {
    try {
      const bookings = await storage.getBookingsByUserId(req.params.userId);
      res.json(bookings);
    } catch (error) {
      handleError(res, error, "Failed to fetch bookings");
    }
  });

  // Get single booking
  app.get("/api/bookings/:id", async (req, res) => {
    try {
      const booking = await storage.getBooking(req.params.id);
      if (!booking) {
        return res.status(404).json({ error: "Booking not found" });
      }
      res.json(booking);
    } catch (error) {
      handleError(res, error, "Failed to fetch booking");
    }
  });

  // Create new booking
  app.post("/api/bookings", async (req, res) => {
    try {
      const validatedData = insertBookingSchema.parse(req.body);

      // Check spot availability and get spot details
      const spot = await storage.getParkingSpot(validatedData.spotId);
      if (!spot || spot.availableSpots <= 0) {
        return res.status(400).json({ error: "Parking spot not available" });
      }

      // Calculate server-side booking amount (security: don't trust client)
      const calculatedAmount = spot.pricePerHour * validatedData.duration;

      // Validate that client-provided amount matches server calculation
      if (validatedData.amount !== calculatedAmount) {
        return res.status(400).json({ 
          error: "Invalid booking amount", 
          expected: calculatedAmount,
          provided: validatedData.amount 
        });
      }

      // Check if user has sufficient wallet balance
      const wallet = await storage.getUserWallet(validatedData.userId);
      if (!wallet || wallet.balance < calculatedAmount) {
        return res.status(400).json({ error: "Insufficient wallet balance" });
      }

      const booking = await storage.createBooking({
        ...validatedData,
        amount: calculatedAmount // Use server-calculated amount, not client-provided
      });

      // Update spot availability
      await storage.updateParkingSpot(validatedData.spotId, {
        availableSpots: spot.availableSpots - 1
      });

      res.status(201).json(booking);
    } catch (error) {
      if (error.name === "ZodError") {
        return handleValidationError(res, error);
      }
      handleError(res, error, "Failed to create booking");
    }
  });

  // Update booking status
  app.patch("/api/bookings/:id", async (req, res) => {
    try {
      const updates = req.body;

      // Validate status transitions
      if (updates.status && !["confirmed", "active", "completed", "cancelled"].includes(updates.status)) {
        return res.status(400).json({ error: "Invalid booking status" });
      }

      const updatedBooking = await storage.updateBooking(req.params.id, updates);
      if (!updatedBooking) {
        return res.status(404).json({ error: "Booking not found" });
      }
      res.json(updatedBooking);
    } catch (error) {
      handleError(res, error, "Failed to update booking");
    }
  });

  // ========================================
  // WALLET ROUTES
  // ========================================

  // Get user wallet
  app.get("/api/wallet/:userId", async (req, res) => {
    try {
      const wallet = await storage.getUserWallet(req.params.userId);
      if (!wallet) {
        return res.status(404).json({ error: "Wallet not found" });
      }
      res.json(wallet);
    } catch (error) {
      handleError(res, error, "Failed to fetch wallet");
    }
  });

  // Get wallet transactions
  app.get("/api/wallet/:userId/transactions", async (req, res) => {
    try {
      const transactions = await storage.getWalletTransactionsByUserId(req.params.userId);
      res.json(transactions);
    } catch (error) {
      handleError(res, error, "Failed to fetch transactions");
    }
  });

  // Add money to wallet
  app.post("/api/wallet/:userId/add-money", async (req, res) => {
    try {
      const { amount, paymentMethod } = req.body;

      if (!amount || amount <= 0) {
        return res.status(400).json({ error: "Invalid amount" });
      }

      // Create credit transaction
      const transaction = await storage.createWalletTransaction({
        userId: req.params.userId,
        type: "credit",
        amount,
        description: "Wallet top-up",
        status: "completed",
        paymentMethod: paymentMethod || "UPI"
      });

      // Update wallet balance
      const updatedWallet = await storage.updateWalletBalance(req.params.userId, amount);

      res.json({ transaction, wallet: updatedWallet });
    } catch (error) {
      handleError(res, error, "Failed to add money to wallet");
    }
  });

  // ========================================
  // USER & VEHICLE ROUTES
  // ========================================

  // Get user vehicles
  app.get("/api/users/:userId/vehicles", async (req, res) => {
    try {
      const vehicles = await storage.getVehiclesByUserId(req.params.userId);
      res.json(vehicles);
    } catch (error) {
      handleError(res, error, "Failed to fetch vehicles");
    }
  });

  // Add user vehicle
  app.post("/api/users/:userId/vehicles", async (req, res) => {
    try {
      const vehicleData = { ...req.body, userId: req.params.userId };
      const validatedData = insertVehicleSchema.parse(vehicleData);
      const vehicle = await storage.createVehicle(validatedData);
      res.status(201).json(vehicle);
    } catch (error) {
      if (error.name === "ZodError") {
        return handleValidationError(res, error);
      }
      handleError(res, error, "Failed to add vehicle");
    }
  });

  // Update vehicle
  app.patch("/api/vehicles/:id", async (req, res) => {
    try {
      const updates = req.body;
      const updatedVehicle = await storage.updateVehicle(req.params.id, updates);
      if (!updatedVehicle) {
        return res.status(404).json({ error: "Vehicle not found" });
      }
      res.json(updatedVehicle);
    } catch (error) {
      handleError(res, error, "Failed to update vehicle");
    }
  });

  // ========================================
  // VENDOR ROUTES
  // ========================================

  // Get vendor profile
  app.get("/api/vendors/:userId/profile", async (req, res) => {
    try {
      const profile = await storage.getVendorProfile(req.params.userId);
      if (!profile) {
        return res.status(404).json({ error: "Vendor profile not found" });
      }
      res.json(profile);
    } catch (error) {
      handleError(res, error, "Failed to fetch vendor profile");
    }
  });

  // Create vendor profile
  app.post("/api/vendors/:userId/profile", async (req, res) => {
    try {
      const profileData = { ...req.body, userId: req.params.userId };
      const validatedData = insertVendorProfileSchema.parse(profileData);
      const profile = await storage.createVendorProfile(validatedData);

      // Update user type to vendor
      await storage.updateUser(req.params.userId, { userType: "vendor" });

      res.status(201).json(profile);
    } catch (error) {
      if (error.name === "ZodError") {
        return handleValidationError(res, error);
      }
      handleError(res, error, "Failed to create vendor profile");
    }
  });

  // Update vendor profile
  app.patch("/api/vendors/:userId/profile", async (req, res) => {
    try {
      const updates = req.body;
      const updatedProfile = await storage.updateVendorProfile(req.params.userId, updates);
      if (!updatedProfile) {
        return res.status(404).json({ error: "Vendor profile not found" });
      }
      res.json(updatedProfile);
    } catch (error) {
      handleError(res, error, "Failed to update vendor profile");
    }
  });

  // ========================================
  // USER AUTHENTICATION ROUTES
  // ========================================

  // Create user (registration)
  app.post("/api/users", async (req, res) => {
    try {
      const validatedData = insertUserSchema.parse(req.body);

      // Check if username already exists
      const existingUser = await storage.getUserByUsername(validatedData.username);
      if (existingUser) {
        return res.status(409).json({ error: "Username already exists" });
      }

      const user = await storage.createUser(validatedData);

      // Remove password from response
      const { password, ...userResponse } = user;
      res.status(201).json(userResponse);
    } catch (error) {
      if (error.name === "ZodError") {
        return handleValidationError(res, error);
      }
      handleError(res, error, "Failed to create user");
    }
  });

  // Get user profile
  app.get("/api/users/:id", async (req, res) => {
    try {
      const user = await storage.getUser(req.params.id);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      // Remove password from response
      const { password, ...userResponse } = user;
      res.json(userResponse);
    } catch (error) {
      handleError(res, error, "Failed to fetch user");
    }
  });

  // Update user profile
  app.patch("/api/users/:id", async (req, res) => {
    try {
      const updates = req.body;
      // Security: only allow safe field updates
      const allowedFields = ['fullName', 'email', 'phone'];
      const safeUpdates = Object.keys(updates)
        .filter(key => allowedFields.includes(key))
        .reduce((obj, key) => {
          obj[key] = updates[key];
          return obj;
        }, {} as any);

      const updatedUser = await storage.updateUser(req.params.id, safeUpdates);
      if (!updatedUser) {
        return res.status(404).json({ error: "User not found" });
      }

      // Remove password from response
      const { password, ...userResponse } = updatedUser;
      res.json(userResponse);
    } catch (error) {
      handleError(res, error, "Failed to update user");
    }
  });

  // ========================================
  // ANALYTICS & STATS ROUTES
  // ========================================

  // Get dashboard stats
  app.get("/api/stats/:userId", async (req, res) => {
    try {
      const [bookings, wallet, vehicles] = await Promise.all([
        storage.getBookingsByUserId(req.params.userId),
        storage.getUserWallet(req.params.userId),
        storage.getVehiclesByUserId(req.params.userId)
      ]);

      const stats = {
        totalBookings: bookings.length,
        activeBookings: bookings.filter(b => b.status === 'active').length,
        walletBalance: wallet?.balance || 0,
        totalVehicles: vehicles.length
      };

      res.json(stats);
    } catch (error) {
      handleError(res, error, "Failed to fetch stats");
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

server/storage.ts.content:
import { type User, type InsertUser, type ParkingSpot, type InsertParkingSpot, type Booking, type InsertBooking, type WalletTransaction, type InsertWalletTransaction, type UserWallet, type InsertUserWallet, type Vehicle, type InsertVehicle, type VendorProfile, type InsertVendorProfile } from "@shared/schema";
import { randomUUID } from "crypto";

export interface IStorage {
  // User operations
  getUser(id: string): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;
  updateUser(id: string, updates: Partial<User>): Promise<User | undefined>;

  // Vehicle operations
  getVehiclesByUserId(userId: string): Promise<Vehicle[]>;
  createVehicle(vehicle: InsertVehicle): Promise<Vehicle>;
  updateVehicle(id: string, updates: Partial<Vehicle>): Promise<Vehicle | undefined>;

  // Parking spot operations
  getAllParkingSpots(): Promise<ParkingSpot[]>;
  getParkingSpotsWithFilters(query?: string, city?: string): Promise<ParkingSpot[]>;
  getParkingSpot(id: string): Promise<ParkingSpot | undefined>;
  createParkingSpot(spot: InsertParkingSpot): Promise<ParkingSpot>;
  updateParkingSpot(id: string, updates: Partial<ParkingSpot>): Promise<ParkingSpot | undefined>;

  // Booking operations
  getBookingsByUserId(userId: string): Promise<Booking[]>;
  getBooking(id: string): Promise<Booking | undefined>;
  createBooking(booking: InsertBooking): Promise<Booking>;
  updateBooking(id: string, updates: Partial<Booking>): Promise<Booking | undefined>;

  // Wallet operations
  getUserWallet(userId: string): Promise<UserWallet | undefined>;
  createUserWallet(wallet: InsertUserWallet): Promise<UserWallet>;
  updateWalletBalance(userId: string, amount: number): Promise<UserWallet | undefined>;
  getWalletTransactionsByUserId(userId: string): Promise<WalletTransaction[]>;
  createWalletTransaction(transaction: InsertWalletTransaction): Promise<WalletTransaction>;

  // Vendor operations
  getVendorProfile(userId: string): Promise<VendorProfile | undefined>;
  createVendorProfile(profile: InsertVendorProfile): Promise<VendorProfile>;
  updateVendorProfile(userId: string, updates: Partial<VendorProfile>): Promise<VendorProfile | undefined>;
}

export class MemStorage implements IStorage {
  private users: Map<string, User>;
  private vehicles: Map<string, Vehicle>;
  private parkingSpots: Map<string, ParkingSpot>;
  private bookings: Map<string, Booking>;
  private walletTransactions: Map<string, WalletTransaction>;
  private userWallets: Map<string, UserWallet>;
  private vendorProfiles: Map<string, VendorProfile>;

  constructor() {
    this.users = new Map();
    this.vehicles = new Map();
    this.parkingSpots = new Map();
    this.bookings = new Map();
    this.walletTransactions = new Map();
    this.userWallets = new Map();
    this.vendorProfiles = new Map();

    // Initialize with some sample data
    this.initializeSampleData();
  }

  private async initializeSampleData() {
    // Create sample parking spots
    const sampleSpots: ParkingSpot[] = [
      {
        id: "spot-1",
        vendorId: "vendor-1",
        name: "Premium Spot - CP",
        address: "Connaught Place, New Delhi",
        city: "Delhi",
        latitude: "28.6315",
        longitude: "77.2167",
        spotType: "premium",
        pricePerHour: 45,
        totalSpots: 20,
        availableSpots: 5,
        rating: "4.8",
        reviews: 124,
        viewers: 3,
        amenities: ["CCTV", "Security", "Covered"],
        isActive: true,
        createdAt: new Date(),
      },
      {
        id: "spot-2",
        vendorId: "vendor-2",
        name: "Saver Parking",
        address: "Sector 18, Noida",
        city: "Noida",
        latitude: "28.5709",
        longitude: "77.3261",
        spotType: "saver",
        pricePerHour: 25,
        totalSpots: 15,
        availableSpots: 2,
        rating: "4.2",
        reviews: 67,
        viewers: 8,
        amenities: ["Open Air", "Security"],
        isActive: true,
        createdAt: new Date(),
      },
      {
        id: "spot-3",
        vendorId: "vendor-3",
        name: "Mall Parking - DLF",
        address: "DLF Phase 1, Gurgaon",
        city: "Gurgaon",
        latitude: "28.4595",
        longitude: "77.0266",
        spotType: "suggested",
        pricePerHour: 35,
        totalSpots: 30,
        availableSpots: 12,
        rating: "4.6",
        reviews: 89,
        viewers: 2,
        amenities: ["Mall Access", "Food Court", "CCTV"],
        isActive: true,
        createdAt: new Date(),
      }
    ];

    sampleSpots.forEach(spot => {
      this.parkingSpots.set(spot.id, spot);
    });
  }

  // User operations
  async getUser(id: string): Promise<User | undefined> {
    return this.users.get(id);
  }

  async getUserByUsername(username: string): Promise<User | undefined> {
    return Array.from(this.users.values()).find(
      (user) => user.username === username,
    );
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const id = randomUUID();
    const user: User = { 
      ...insertUser, 
      id, 
      createdAt: new Date(),
      fullName: insertUser.fullName || null,
      email: insertUser.email || null,
      phone: insertUser.phone || null,
      userType: insertUser.userType || "user"
    };
    this.users.set(id, user);

    // Create default wallet for new user
    await this.createUserWallet({ userId: id, balance: 0 });

    return user;
  }

  async updateUser(id: string, updates: Partial<User>): Promise<User | undefined> {
    const user = this.users.get(id);
    if (!user) return undefined;

    const updatedUser = { ...user, ...updates };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  // Vehicle operations
  async getVehiclesByUserId(userId: string): Promise<Vehicle[]> {
    return Array.from(this.vehicles.values()).filter(vehicle => vehicle.userId === userId);
  }

  async createVehicle(insertVehicle: InsertVehicle): Promise<Vehicle> {
    const id = randomUUID();
    const vehicle: Vehicle = { 
      ...insertVehicle, 
      id,
      vehicleNumber: insertVehicle.vehicleNumber || null,
      rcUploaded: insertVehicle.rcUploaded || null
    };
    this.vehicles.set(id, vehicle);
    return vehicle;
  }

  async updateVehicle(id: string, updates: Partial<Vehicle>): Promise<Vehicle | undefined> {
    const vehicle = this.vehicles.get(id);
    if (!vehicle) return undefined;

    const updatedVehicle = { ...vehicle, ...updates };
    this.vehicles.set(id, updatedVehicle);
    return updatedVehicle;
  }

  // Parking spot operations
  async getAllParkingSpots(): Promise<ParkingSpot[]> {
    return Array.from(this.parkingSpots.values()).filter(spot => spot.isActive);
  }

  async getParkingSpotsWithFilters(query?: string, city?: string): Promise<ParkingSpot[]> {
    let spots = Array.from(this.parkingSpots.values()).filter(spot => spot.isActive);

    if (query) {
      spots = spots.filter(spot => 
        spot.name.toLowerCase().includes(query.toLowerCase()) ||
        spot.address.toLowerCase().includes(query.toLowerCase()) ||
        spot.spotType.toLowerCase().includes(query.toLowerCase())
      );
    }

    if (city) {
      spots = spots.filter(spot => spot.city.toLowerCase() === city.toLowerCase());
    }

    return spots;
  }

  async getParkingSpot(id: string): Promise<ParkingSpot | undefined> {
    return this.parkingSpots.get(id);
  }

  async createParkingSpot(insertSpot: InsertParkingSpot): Promise<ParkingSpot> {
    const id = randomUUID();
    const spot: ParkingSpot = { 
      ...insertSpot, 
      id, 
      createdAt: new Date(),
      latitude: insertSpot.latitude || null,
      longitude: insertSpot.longitude || null,
      rating: insertSpot.rating || "0.0",
      reviews: insertSpot.reviews || 0,
      viewers: insertSpot.viewers || 0,
      amenities: insertSpot.amenities || null,
      isActive: insertSpot.isActive !== undefined ? insertSpot.isActive : true
    };
    this.parkingSpots.set(id, spot);
    return spot;
  }

  async updateParkingSpot(id: string, updates: Partial<ParkingSpot>): Promise<ParkingSpot | undefined> {
    const spot = this.parkingSpots.get(id);
    if (!spot) return undefined;

    const updatedSpot = { ...spot, ...updates };
    this.parkingSpots.set(id, updatedSpot);
    return updatedSpot;
  }

  // Booking operations
  async getBookingsByUserId(userId: string): Promise<Booking[]> {
    return Array.from(this.bookings.values())
      .filter(booking => booking.userId === userId)
      .sort((a, b) => new Date(b.createdAt!).getTime() - new Date(a.createdAt!).getTime());
  }

  async getBooking(id: string): Promise<Booking | undefined> {
    return this.bookings.get(id);
  }

  async createBooking(insertBooking: InsertBooking): Promise<Booking> {
    const id = randomUUID();
    const booking: Booking = { 
      ...insertBooking, 
      id, 
      createdAt: new Date(),
      status: insertBooking.status || "confirmed",
      vehicleSpot: insertBooking.vehicleSpot || null,
      hostContact: insertBooking.hostContact || null
    };
    this.bookings.set(id, booking);

    // Create wallet transaction for booking payment
    await this.createWalletTransaction({
      userId: booking.userId,
      type: "debit",
      amount: booking.amount,
      description: `Parking booking - ${booking.id}`,
      status: "completed",
      relatedBookingId: booking.id,
      paymentMethod: null
    });

    // Update wallet balance
    await this.updateWalletBalance(booking.userId, -booking.amount);

    return booking;
  }

  async updateBooking(id: string, updates: Partial<Booking>): Promise<Booking | undefined> {
    const booking = this.bookings.get(id);
    if (!booking) return undefined;

    const updatedBooking = { ...booking, ...updates };
    this.bookings.set(id, updatedBooking);
    return updatedBooking;
  }

  // Wallet operations
  async getUserWallet(userId: string): Promise<UserWallet | undefined> {
    return Array.from(this.userWallets.values()).find(wallet => wallet.userId === userId);
  }

  async createUserWallet(insertWallet: InsertUserWallet): Promise<UserWallet> {
    const id = randomUUID();
    const wallet: UserWallet = { 
      ...insertWallet, 
      id, 
      updatedAt: new Date(),
      balance: insertWallet.balance || 0
    };
    this.userWallets.set(id, wallet);
    return wallet;
  }

  async updateWalletBalance(userId: string, amount: number): Promise<UserWallet | undefined> {
    const wallet = Array.from(this.userWallets.values()).find(w => w.userId === userId);
    if (!wallet) return undefined;

    const updatedWallet = { ...wallet, balance: wallet.balance + amount, updatedAt: new Date() };
    this.userWallets.set(wallet.id, updatedWallet);
    return updatedWallet;
  }

  async getWalletTransactionsByUserId(userId: string): Promise<WalletTransaction[]> {
    return Array.from(this.walletTransactions.values())
      .filter(transaction => transaction.userId === userId)
      .sort((a, b) => new Date(b.createdAt!).getTime() - new Date(a.createdAt!).getTime());
  }

  async createWalletTransaction(insertTransaction: InsertWalletTransaction): Promise<WalletTransaction> {
    const id = randomUUID();
    const transaction: WalletTransaction = { 
      ...insertTransaction, 
      id, 
      createdAt: new Date(),
      status: insertTransaction.status || "completed",
      relatedBookingId: insertTransaction.relatedBookingId || null,
      paymentMethod: insertTransaction.paymentMethod || null
    };
    this.walletTransactions.set(id, transaction);
    return transaction;
  }

  // Vendor operations
  async getVendorProfile(userId: string): Promise<VendorProfile | undefined> {
    return Array.from(this.vendorProfiles.values()).find(profile => profile.userId === userId);
  }

  async createVendorProfile(insertProfile: InsertVendorProfile): Promise<VendorProfile> {
    const id = randomUUID();
    const profile: VendorProfile = { 
      ...insertProfile, 
      id, 
      createdAt: new Date(),
      businessName: insertProfile.businessName || null,
      panNumber: insertProfile.panNumber || null,
      gstNumber: insertProfile.gstNumber || null,
      bankAccountNumber: insertProfile.bankAccountNumber || null,
      ifscCode: insertProfile.ifscCode || null,
      documentsUploaded: insertProfile.documentsUploaded || null,
      isVerified: insertProfile.isVerified || null
    };
    this.vendorProfiles.set(id, profile);
    return profile;
  }

  async updateVendorProfile(userId: string, updates: Partial<VendorProfile>): Promise<VendorProfile | undefined> {
    const profile = Array.from(this.vendorProfiles.values()).find(p => p.userId === userId);
    if (!profile) return undefined;

    const updatedProfile = { ...profile, ...updates };
    this.vendorProfiles.set(profile.id, updatedProfile);
    return updatedProfile;
  }
}

export const storage = new MemStorage();

